def transform(grid):
    # Recolor isolated/partial objects when their shape is represented by a
    # more complete object of another color.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 3 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx))
                        stack.append((yy,xx))
            comps.append((color, cells))

    # Find exact shape copies (up to translation) and use the color of the
    # larger matching component for the smaller one.
    shapes = {}
    for color, cells in comps:
        minr = min(y for y,x in cells)
        minc = min(x for y,x in cells)
        shape = frozenset((y-minr, x-minc) for y,x in cells)
        shapes.setdefault(shape, []).append((color, cells))
    for entries in shapes.values():
        if len({c for c, _ in entries}) > 1:
            largest = max(entries, key=lambda e: len(e[1]))
            target = largest[0]
            for color, cells in entries:
                if color != target and len(cells) <= len(largest[1]):
                    for y,x in cells:
                        out[y][x] = target
    return out
